internal object DuaMaiDraft3 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_travel_full" to DuaText("पूर्ण यात्रा प्रार्थना", "ऐ अल्लाह, हम एहि यात्रा मे अहाँ सँ धर्म और धर्मपरायणता के लेल प्रार्थना करैत छी, आ एहन काज के लेल जे अहाँ के प्रसन्न करे। ऐ अल्लाह, हमरा लेल ई यात्रा आसान बनाउ आ एकर दूरी कम करू। ऐ अल्लाह, अहाँ यात्रा मे साथी आ परिवारक संरक्षक छी।", "यात्रा पर निकलैत समय,'सुभानल्लधी सखरा'क बाद।", "पूरा सुन्नत यात्रा दुआ।"),
        "dua_return_travel" to DuaText("यात्रा सँ वापसी", "हम सभ पश्चाताप करैत, अपन प्रभुक पूजा करैत आ हुनकर स्तुति करैत, फेरैत छी।", "यात्रा सँ घुरैत।", "पैगम्बर सल्लल्लाहु अलैहि वसल्लम यात्रा सँ घुरैत ई कहलनि।"),
        "dua_farewell_traveller" to DuaText("एकटा यात्रीकेँ विदाई", "हम अहाँक धर्म, अहाँक विश्वास आ अहाँक काजक परिणाम अल्लाहकेँ सौंपैत छी।", "जखन कोनो यात्रीकेँ विदाई दैत छी।", "जे अल्लाहकेँ देल गेल अछि, ओ कहियो नहि हारि जाइत अछि।"),
        "dua_entering_town" to DuaText("एक जगह पर रुकना", "हम अल्लाह के सिद्ध वचन मे शरण चाहैत छी जे ओ सब दुष्टता सँ बचैत अछि जे ओ पैदा कयने छथि।", "जखन कोनो स्थान पर रुकैत छी वा कोनो नव नगरमे पहुँचैत अछि।", "जाबत धरि ओ ओतऽसँ नहि चलि जायत, ताबत धरि ओकरा कोनो हानि नहि होयत।"),
        "dua_boarding_ship" to DuaText("जहाज/वाहन पर चढ़ना", "ई जहाज आ एकर लंगर अल्लाह के नाम पर अछि। निश्चय ही हमर रब क्षमाशील, दयावान छथि।", "जहाज या वाहन मे चढ़ैत समय-पैगम्बर नूह (अ. स.) के शब्द।", "एकटा कुरानिक श्लोक-नूहक (ए. एस.) सन्दूक दुआ।"),
        "dua_istighfar_hayyul_qayyum" to DuaText("हयुल-कयुमक संग इस्तिघफर", "हम अल्लाह सँ क्षमा माँगैत छी, जकरा छोड़ि कोनो देवता, जीवित, पालनकर्ता नहि अछि, आ हम पश्चाताप करैत हुनका लग फिरैत छी।", "पश्चाताप लेल।", "ओकर पाप क्षमा भऽ जायत अछि, भले ओ युद्धक्षेत्रसँ भाग गेल हो।"),
        "dua_rabbighfir_warham" to DuaText("रब्बीघफिर वारहम", "हे हमर प्रभु, क्षमा करू आ दया करू, कारण अहाँ सभ दया करय वला सभ मे सबसँ नीक छी।", "एकटा कुरानिक दुआ-क्षमा आ दयाक लेल।", "सूरह अल-मु'मिनुनक अन्तिम श्लोक।"),
        "dua_majlis_kaffarah" to DuaText("कफरात अल-मजलिस", "महिमावान छी अहाँ, हे अल्लाह, आ प्रशंसा अहाँ पर होअय। हम गवाही दैत छी जे अहाँक अतिरिक्त कोनो देवता नहि अछि। हम अहाँक क्षमा माँगैत छी आ पश्चाताप करैत अहाँ दिस मुड़ैत छी।", "जखन कोनो सभा सँ उठैत छी।", "सभामे जे किछु गलत कहल गेल छल, ई ओकर प्रायश्चित बनि जाइत अछि।"),
        "dua_jami_forgiveness" to DuaText("व्यापक क्षमा", "ऐ अल्लाह, हमर गलती, हमर अज्ञानता, हमर मामिलामे हमर अति आ अहाँ हमरा सँ बेसी जे किछु जनैत छी से सब हमरा क्षमा कऽ दियौक।", "पैगम्बर सल्लल्लाहु अलैहि वसल्लम के एक व्यापक दुआ।", "पैगम्बर सल्लल्लाहु अलैहि वसल्लम एहि दुआ केँ बनबैत छलाह।"),
        "dua_parents_nuh" to DuaText("माता-पिता के लेल नूह (ए. एस.) क दुआ", "हे हमर प्रभु, हमर माता-पिता, जे केओ हमर घर मे विश्वासक रूपमे प्रवेश करे, आ सभ विश्वासक पुरुष आ महिला सभ केँ क्षमा कऽ दियौक।", "अपन माता-पिता आ विश्वासी सभक लेल।", "पैगम्बर नूह (अ. स.) के दुआ।"),
        "dua_shukr_parents" to DuaText("माता-पिता आ धार्मिक सन्तानक प्रति आभार", "हे हमर प्रभु, अहाँ हमरा आ हमर माता-पिता पर जे अनुग्रह कयलहुँ, ताहि लेल हमरा आभारी होयबाक अनुमति दियौक, आ एहन नीक काज करी जे अहाँकेँ प्रसन्न करे, आ हमर सन्तानसभकेँ धर्मी बनाए। हम पश्चाताप करैत अहाँ दिस फिरैत छी आ हम आज्ञाकारी सभक बीच छी।", "चालीस वर्षक आयु धरि पहुँचबाक कुरानिक दुआ।", "आभार, नीक काज आ अपन सन्तानक धार्मिकता-सब एक दुआमे।"),
        "dua_intimacy" to DuaText("वैवाहिक सम्बन्धसँ पहिने", "अल्लाह के नाम पर। ऐ अल्लाह, शयतान केँ हमरा सँ दूर राखू आ शयतान केँ अहाँ हमरा सभ केँ जे दैत छी, ओकरा सँ दूर राखू।", "वैवाहिक सम्बन्धसँ पहिने।", "जँ कोनो बच्चाकेँ सजा देल जायत तऽ शयतान ओकरा कहियो हानि नहि पहुँचय देत।"),
        "dua_ibrahim_children_protection" to DuaText("घर आ बच्चासभक संरक्षण", "हे हमर प्रभु, एहि नगरकेँ सुरक्षित राखू आ हमरा आ हमर बच्चासभ केँ मूर्तिक पूजा सँ दूर राखू।", "पैगम्बर इब्राहिम (अ. स.) क दुआ-शहर आ हुनक बच्चासभक सुरक्षाक लेल।", "तौहिद पर दृढ़ रहबाक लेल दुआ।"),
        "dua_drinking_milk" to DuaText("दूध पीयबा पर", "हे अल्लाह, हमरा सभ पर आशीर्वाद करू आ हमरा सभ केँ एकर बेसी दे।", "दूध पीयबा पर।", "दूध भोजन आ पेय दुनू लेल पर्याप्त अछि।"),
        "dua_iftar_host" to DuaText("जखन दोसरक संग तेजीसँ सम्बन्ध तोड़ैत छी", "उपवास करयवला लोक अहाँ सभक संग अपन उपवास तोड़य, धर्मी लोकनि अहाँक भोजन करे आ स्वर्गदूत सभ अहाँक लेल प्रार्थना करय।", "जखन कोनो व्यक्तिक घर पर व्रत तोड़ैत छी।", "मेजबानक लेल पैगम्बर सल्लल्लाहु अलैहि वसल्लम दुआ।"),
        "dua_seeing_first_fruit" to DuaText("पहिल फल देखलहुँ।", "हे अल्लाह, हमरा सभ केँ हमर फलक आशीर्वाद दियौक, हमर शहर मे आशीर्वाद दियौक, आ हमर सभ केँ हमर सा आ हमर दलदल (माप) मे आशीर्वाद दियौक।", "मौसिमक पहिल फल देखलासँ।", "उपबंध आ नगरमे आशीर्वादक लेल दुआ।"),
        "dua_good_news" to DuaText("सुखद समाचार पर", "प्रशंसा अल्लाह के लेल अछि, जकर कृपा सँ नीक काज पूरा भऽ जाइत अछि।", "शुभ समाचार प्राप्त कयलाक बाद (आ कृतज्ञताक प्रणाम करू)।", "पैगम्बर सल्लल्लाहु अलैहि वसल्लम किछु एहन देखलाक जे हुनका पसन्द आयल।"),
        "dua_looking_mirror" to DuaText("ऐना मे देखू", "ऐ अल्लाह, जेना अहाँ हमर रूप-रूप नीक कयलहुँ, तहिना हमर चरित्र सेहो नीक बना देलहुँ।", "ऐना मे देखैत।", "पैगम्बर सल्लल्लाहु अलैहि वसल्लम ई दुआ (ई ऐनाक उल्लेखके बिना सेहो स्थापित अछि) बनौलनि।"),
        "dua_rabbana_taqabbal" to DuaText("काजक स्वीकृति", "हे हमर प्रभु, हमरा सभ सँ ई स्वीकार करू, निश्चय ही अहाँ सभ सुनने वला, सब किछु जानने वला छी। आ हमर पश्चाताप स्वीकार करू, निश्चय ही अहाँ पश्चाताप करबाक अग्रदूत, दयावान छी।", "काबा के निर्माण के दौरान इब्राहिम आ इस्माइल (ए. एस.) द्वारा पूछा गेल।", "प्रत्येक नीक काजक बाद स्वीकार करबाक लेल दुआ।"),
        "dua_muawwidhat" to DuaText("तीन कुल (मुआव्विदात)", "(सूरह-उल-इखलास) कहू, ओ अल्लाह, एक छथि। अल्लाह, आत्मनिर्भर छथि। ओ न जन्म लैत छथि आ न जन्मैत छथि। आ हुनका सङ्ग कोनो तुलनीय नहि अछि।\n\n(सुरा अल-तलाक) कहू, हम भोरक प्रभु सँ, जे किछु ओ उत्पन्न कयने छथि ओकर बुराई सँ, जे अन्धकार स्थिर भऽ जाइत अछि ओकर बुराई सँ, जे गाँठ पर फुँसैत अछि ओकर बुराई सँ, आ जे ईर्ष्या करैत अछि ओकर बुराई सँ शरण चाहैत छी।\n\n(सूरह-नास) कहू, हम जिन्न आ मानवजाति के बीच सँ मानवजाति के प्रभु, मानवजाति के राजा, मानवजाति के भगवान के शरण चाहैत छी, ओहि दुष्टता सँ जे जिन आ मानव जाति के दिल मे फुसफुसा रहल अछि।", "तीन सूराह प्रत्येक भोर आ साँझ तीन बेर, आ सोबासँ पहिने, हाथ मे उड़ाउ आ शरीर पर पूछि दियौक।", "भोर-साँझ तीन बेर एकर पाठ करब सब किछाक विरुद्ध पर्याप्त अछि।"),
        "dua_sabr" to DuaText("धैर्य आ स्थिरताक लेल", "हमर प्रभु, हमरा सभ पर धैर्य राखू, अपन पैर स्थिर करू आ अविश्वासी लोक सभक विरुद्ध हमरा सभक सहायता करू।", "कठिनता आ टकरावक समय।", "तालूतक सेनाक दुआ।"),
        "dua_rabbana_innana_amanna" to DuaText("क्षमा आ आगिसँ सुरक्षा", "हे हमर प्रभु, हम सभ विश्वास कयने छी, तेँ हमरा सभक पाप क्षमा करी आ आगि के सजा सँ बचा लिअ।", "एकटा कुरानिक दुआ।", "देव-भयक गुणमे एक दुआक उल्लेख अछि।"),
        "dua_rabbana_hab_lana_rahmah" to DuaText("हमर मामिलामे मार्गदर्शन (आशाब अल-कहफ)", "हमर प्रभु, हमरा सभ पर अपना सँ दया करू आ हमरा सभक लेल हमर सभक व्यवहारमे सही मार्गदर्शन तैयार करू।", "गुफाक लोकक दुआ।", "निर्णय आ कठिन परिस्थितिमे मार्गदर्शन।"),
        "dua_musa_faqir" to DuaText("प्रावधान लेल मूसा (ए. एस.) के दुआ", "हे हमर प्रभु, अहाँ हमरा जे किछु नीक वस्तु पठा रहल छी, से हमरा बड्ड आवश्यक अछि।", "प्रावधान आ भलाइक खोज-मद्यानमे मूसा (ए. एस.) क दुआ।", "एहि दुआक बाद अल्लाह मूसाक (अ. स.) लेल घर, काज आ पत्नीक व्यवस्था कयलनि।"),
        "dua_ayyub" to DuaText("अयूब (ए. एस.) के दुआ बीमारीमे", "(हे हमर प्रभु) हमरा हानि पहुँचल अछि आ अहाँ दयालु सभ पर अति दयावान छी।", "बीमारी आ पीड़ा मे।", "अल्लाह अयूब (अ. स.) क दुख दूर कयलनि।"),
        "dua_husn_khatimah" to DuaText("मुसलमानक रूपमे मरू (युसुफ ए. एस.)", "आकाश आ पृथ्वीक निर्माता, अहाँ एहि संसार आ आख़िरत मे हमर रक्षक छी। हमरा मुसलमानक रूपमे मरिऔक आ धर्मपरायण सभक संग हमरा संग सम्मिलित करू।", "नीक अन्त लेल दुआ।", "पैगम्बर युसुफ (अ. स.) के दुआ।"),
        "dua_shaitan_hamazat" to DuaText("शैतानक व्हिस्परसँ शरण", "हे हमर प्रभु, हम दुष्टात्मा सभक फुसफुस सँ अहाँक शरण चाहैत छी, आ हमर प्रभु, अहाँक शरण चाहैत छी, जँ ओ सभ हमरा लग नहि आबि जाय।", "शैतानक फुसफुससँ शरण।", "शरण लेबाक कुरानिक दुआ।"),
        "dua_bad_character" to DuaText("खराब चरित्रसँ शरण", "ऐ अल्लाह, हम अहाँ मे बदनीयारी, अधलाह काज आ अधलाह इच्छा सँ शरण चाहैत छी।", "खराब चरित्र, कर्म आ इच्छा सँ शरण।", "पैगम्बर सल्लल्लाहु अलैहि वसल्लम सँ शरण लेल दुआ।"),
        "dua_zawal_nimah" to DuaText("आशीर्वादक हानि सँ शरण", "ऐ अल्लाह, हम अहाँक आशीर्वादक हानि, अहाँक कल्याणक परिवर्तन, अहाँक आकस्मिक सजा आ अहाँक सभ असन्तोषसँ अहाँमे शरण चाहैत छी।", "आशीर्वाद खोयबाक आ आकस्मिक आपदा सँ शरण।", "पैगम्बर सल्लल्लाहु अलैहि वसल्लम के दुआ।"),
        "dua_useless_knowledge" to DuaText("गैर-लाभकारी ज्ञानसँ शरण", "ऐ अल्लाह, हम अहाँ मे एहन ज्ञान सँ शरण चाहैत छी जे लाभ नहि करैत अछि, एहन हृदय सँ जे डरैत नहि अछि, एहन आत्मा सँ जे कहियो संतुष्ट नहि अछि, आ एहन दुआ सँ जकर उत्तर नहि देल गेल अछि।", "व्यर्थ ज्ञान आ अल्लाहसँ भय रहित हृदयसँ शरण लिअ।", "पैगम्बर सल्लल्लाहु अलैहि वसल्लम सँ शरण लेल दुआ।"),
        "dua_beneficial_knowledge" to DuaText("लाभकारी ज्ञान आ हलाल रिजक", "ऐ अल्लाह, हम अहाँ सँ लाभप्रद ज्ञान, शुद्ध रोजी-रोटी आ स्वीकृत काजक प्रार्थना करैत छी।", "फजर नमाज़क बाद।", "पैगम्बर सल्लल्लाहु अलैहि वसल्लम फजरक नमाज़क बाद ई कहलनि।"),
        "dua_leprosy_diseases" to DuaText("गम्भीर रोगसँ शरण", "हे अल्लाह, हम नील, पागलपन, कुष्ठ रोग आ सभ दुष्ट रोगसँ अहाँक शरण चाहैत छी।", "गम्भीर रोगसँ सुरक्षा।", "स्वास्थ्यक संरक्षण लेल सुन्नत दुआ।"),
        "dua_fear_people" to DuaText("शत्रु वा उत्पीड़क भय", "ऐ अल्लाह, हम अहाँ केँ हुनका सभक सामने रखैत छी आ अहाँ मे हुनक दुष्टता सँ शरण लैत छी।", "जखन कोनो लोक या व्यक्तिक हानिक भय होइत अछि।", "पैगम्बर सल्लल्लाहु अलैहि वसल्लम ई बात ओहि समय कहलनि जखन ओ कोनो लोकसँ डरैत छलाह।"),
        "dua_shirk_protection" to DuaText("छिपी शिर्कसँ सुरक्षा", "ऐ अल्लाह, हम जान-बूझिक संग अहाँक संग कोनो काजक साझी बनाबय सँ अहाँ सँ शरण चाहैत छी, आ जे किछु अनजाने मे करैत छी ताहि लेल क्षमा माँगैत छी।", "दिखावा आ छिपी शिर्कसँ सुरक्षित रहबाक लेल।", "चीनीक रेंगबाक तुलनामे छिपी शिर्क बेसी छिपी रहैत अछि।"),
        "dua_rain" to DuaText("जखन बरखा होइत अछि", "ऐ अल्लाह, एकटा लाभदायक बरखा पठाउ।", "जखन बरखा होइत अछि।", "बरखा एकटा एहन समय अछि जखन दुआ स्वीकार कयल जाइत अछि।"),
        "dua_after_rain" to DuaText("बरखा के बाद", "हमरा सभ पर अल्लाह के उदार अनुग्रह आ हुनकर दया सँ बरखा भेल अछि।", "बरखा के बाद।", "जे ई कहैत अछि से अल्लाह मे विश्वास करैत अछि।"),
        "dua_istisqa" to DuaText("बरखा के लेल माँगना (इस्तिस्का)", "ऐ अल्लाह, हमरा सभ केँ तीन बेर बरखा पठाउ।", "जखन बरखा नहि होइत अछि।", "पैगम्बर सल्लल्लाहु अलैहि वसल्लम शुक्रदिनक उपदेशमे ई दुआ कयलनि आ बरखा भेल।"),
        "dua_heavy_rain" to DuaText("अत्यधिक वर्षा", "ऐ अल्लाह, (ई) हमरा सभ पर नहि, बल्कि हमरा सभ पर पड़य।", "जखन बहुत बेसी बरखा होइत अछि।", "पैगम्बर सल्लल्लाहु अलैहि वसल्लम के दुआ सँ बादलों दूर चलि गेल।"),
        "dua_wind" to DuaText("जखन हवा बहैत अछि", "ऐ अल्लाह, हम अहां सँ ओकर नीक, ओकर भीतरक नीक आ ओकर नीक जे एकरा पठायल गेल छल से माँगैत छी, आ हम अहाँ सँ ओकर अधलाह, ओकर भीतरक अधलाह आ ओकर अधलाह सँ शरण लैत छी।", "जखन तेज हवा वा बवंडर चलैत अछि।", "पैगम्बर सल्लल्लाहु अलैहि वसल्लम बवंडरक समय ई दुआ बनौलनि।"),
        "dua_thunder" to DuaText("गर्जन सुनै", "महिमावान छथि ओ, जकर गर्जन हुनकर प्रशंसा करैत अछि आ स्वर्गदूत सभ हुनका भय सँ महिमावान छथि।", "गर्जन सुनबा पर-अब्दुल्ला इब्न अज़-जुबैर (रा.) क प्रथा।", "सूरह अर-राद (13:13) सँ लेल गेल।"),
    )
}
